INSERT INTO public.quiz_questions (id, subject, topic, gs_paper, question_en, question_hi, options_en, options_hi, correct_index, explanation_en, explanation_hi, source_book)
VALUES ('qq-1', 'Polity & Governance', 'Constitutional Bodies & Fiscal Federalism', 'GS-2', 'With reference to the Finance Commission of India, consider the following statements:', 'भारत के वित्त आयोग के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:', '{"1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"}', '{"केवल 1 और 2","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"}', 1, 'Statement 1 is correct (Art. 280(1)). Statement 2 is incorrect: Recommendations are advisory in nature and not legally binding, though by constitutional convention governments accept tax-sharing recommendations. Statement 3 is correct (Art. 280(2) & Finance Commission (Miscellaneous Provisions) Act, 1951).', 'कथन 1 सही है (अनुच्छेद 280(1))। कथन 2 गलत है: सिफारिशें केवल सलाहकारी प्रकृति की होती हैं और बाध्यकारी नहीं हैं। कथन 3 सही है (अनुच्छेद 280(2) और वित्त आयोग अधिनियम, 1951)।', 'Indian Polity — M. Laxmikanth (Chapter: Finance Commission)')
ON CONFLICT (id) DO NOTHING;

INSERT INTO public.quiz_questions (id, subject, topic, gs_paper, question_en, question_hi, options_en, options_hi, correct_index, explanation_en, explanation_hi, source_book)
VALUES ('qq-2', 'Indian Economy', 'Monetary Policy & Digital Currency', 'GS-3', 'Consider the following statements regarding the Central Bank Digital Currency (CBDC / e-Rupee) issued by the Reserve Bank of India:', 'भारतीय रिजर्व बैंक द्वारा जारी केंद्रीय बैंक डिजिटल मुद्रा (CBDC / ई-रुपया) के संदर्भ में निम्नलिखित कथनों पर विचार कीजिए:', '{"1 and 2 only","1 and 3 only","2 and 3 only","1, 2 and 3"}', '{"केवल 1 और 2","केवल 1 और 3","केवल 2 और 3","1, 2 और 3"}', 1, 'Statement 1 is correct (sovereign currency liability of RBI). Statement 2 is incorrect: CBDC is non-interest bearing by design to prevent commercial bank deposit disintermediation. Statement 3 is correct (Finance Act 2022 amended Section 2(aiv) of RBI Act, 1934).', 'कथन 1 सही है (आरबीआई की संप्रभु देयता)। कथन 2 गलत है: सीबीडीसी गैर-ब्याज वाली मुद्रा है ताकि वाणिज्यिक बैंकों के जमा आधार को नुकसान न पहुंचे। कथन 3 सही है (वित्त अधिनियम 2022 द्वारा आरबीआई अधिनियम की धारा 2(aiv) में संशोधन)।', 'RBI Report on Currency and Finance & Economic Survey')
ON CONFLICT (id) DO NOTHING;

